import{z as A,x as p,o as i,c as m,q as o,j as l,D as E,d as t,s,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"偏振与矢量成像","description":"","frontmatter":{"title":"偏振与矢量成像","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/vector-imaging.md","filePath":"litho/vector-imaging.md","lastUpdated":1791413859000}'),B={name:"litho/vector-imaging.md"};function h(d,a,T,f,u,c){const r=p("Mermaid");return i(),m("div",null,[a[2]||(a[2]=o('<h1 id="偏振与矢量成像" tabindex="-1">偏振与矢量成像 <a class="header-anchor" href="#偏振与矢量成像" aria-label="Permalink to &quot;偏振与矢量成像&quot;">​</a></h1><div class="epigraph"><p>孔径角一大，电场不再能收成一个标量 $U$；s 与 p 在像面的干涉效率不同，胶里沉积的是矢量场的能量，不是 $|U|^2$。</p><footer>—— 据 Born &amp; Wolf 对电磁边值与偏振的讨论，以及 Mack、Levinson 对高 NA 矢量成像的产线表述整理</footer></div><p><a href="/litho/bossung-curve">上一课</a>（Bossung 曲线）。在此之上，离焦写成标量光瞳上的二次相位，\\(C(z)\\) 与 NILS\\((z)\\) 都还在标量空中像里读。缺口是：\\(\\mathrm{NA}\\gtrsim 0.7\\)（浸没到 1.35）时，边缘光线的电场有不可忽略的纵向分量，TM 两束几乎不相干相加，标量对比度过于乐观。本课把强度升级成胶内能量沉积。非偏振照明为什么只是平均、取向正交的密线为什么无法共用同一纯 TE，留给<a href="/litho/te-tm-polarization">下一课</a>；产线 CD 公式仍留给后面的<a href="/litho/rayleigh-litho">瑞利判据</a>课，不要在这里提前写 \\(k_1\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标量模型假定偏振与传播方向无关：光瞳函数乘复振幅，像面取模方。高 NA 下这套接口破了。同一对衍射级，TE（s）电场彼此平行，干涉条纹深；TM（p）电场沿各自的 \\(\\mathbf{k}\\)，夹角接近 \\(2\\theta\\) 时交叉项 \\(\\mathbf{E}_1\\cdot\\mathbf{E}_2^*\\) 变小，暗区抬高。上一课看到的「离焦毁掉 NILS」，有一部分其实是偏振损失被误写成焦深。</p><p><span class="marginnote">直觉类比：两把方向平行的小刷子沿同一条缝来回刷，深浅能完全叠上，这是 TE；两把刷子彼此拧开一个角度，重叠的痕迹就互相抵掉一部分，这是 TM——夹角越大，抵得越狠。</span></p><p>缺口因此是给空中像一个矢量定义，而不是开始挑偶极的偏振方向。没有这一定义，后课的浸没、离轴照明会把「TM 对比掉了」和「\\(\\sigma\\) 选错了」缠在一起。</p><h3 id="像面强度不是真空里的-e-2" tabindex="-1">像面强度不是真空里的 |E|² <a class="header-anchor" href="#像面强度不是真空里的-e-2" aria-label="Permalink to &quot;像面强度不是真空里的 |E|²&quot;">​</a></h3><p>光刻胶要的是被吸收的能量密度，与胶内电场（再乘吸收）有关，不是空气/水里的坡印廷矢量随便取一个分量。折射率台阶在胶界面上改变透射的 s/p 比，驻波沿 \\(z\\) 再调制一层。本课允许把「矢量空中像」说成指定平面上的能量沉积 \\(I_\\mathrm{abs}(x,y)\\)；薄膜堆栈的严格分层计算是材料缺口，这里只要求不再写标量 \\(|U|^2\\)。</p><p><span class="marginnote">「矢量 TCC」把 Hopkins 的重叠积分换成偏振通道。部分相干课的 \\(\\sigma\\) 定义不变，变的是每个源点携带的琼斯矢量如何进光瞳。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把进入光瞳的每条光线写成局部 s/p（或 Jones），经投影后在像面矢量叠加，再对源点做强度积分。计算上这就是矢量 TCC 或偏振分解的和差相干。照明侧加偏振控制：让密线的关键方向走 TE，避免 TM 主导的那一组节距。这是后课离轴照明的偏振附件，本课只提供接口。</p><p><span class="marginnote">「琼斯矢量」就是给每条光线发一张二维小卡片，记下电场在两个互相垂直方向上的复振幅；把标量计算里的每个数换成这张卡片，就是矢量 TCC 的全部升级，其他框架不动。</span></p><p>标量离焦相位仍然乘在每个偏振通道上。矢量效应与焦深叠加，不是互相替代：TM 损失在最佳焦距就已经存在，离焦再叠加二次相位。</p><h3 id="浸没把夹角做大" tabindex="-1">浸没把夹角做大 <a class="header-anchor" href="#浸没把夹角做大" aria-label="Permalink to &quot;浸没把夹角做大&quot;">​</a></h3><p>\\(\\mathrm{NA}=n\\sin\\theta\\)。水把 \\(n\\) 抬到约 1.44，同样的空间频率对应更大的光线夹角，TM 退化来得更早。干式 0.93 已经需要小心；1.35 必须默认矢量模型。本课不讲水层流体，只钉：改 \\(n\\) 就是改夹角，也就是改偏振对比。</p>',16)),(i(),l(n,null,{default:E(()=>[s(r,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20NA%5B%22%E9%AB%98%20NA%20%E5%A4%A7%E5%A4%B9%E8%A7%92%22%5D%20--%3E%20POL%5B%22s%20%2F%20p%20%E9%80%9A%E9%81%93%22%5D%0A%20%20POL%20--%3E%20TE%5B%22TE%20%E5%B9%B2%E6%B6%89%E6%B7%B1%22%5D%0A%20%20POL%20--%3E%20TM%5B%22TM%20%E4%BA%A4%E5%8F%89%E9%A1%B9%E5%8F%98%E5%BC%B1%22%5D%0A%20%20TM%20--%3E%20I%5B%22%E8%83%B6%E5%86%85%E8%83%BD%E9%87%8F%E6%B2%89%E7%A7%AF%22%5D%0A%20%20TE%20--%3E%20I%0A%20%20I%20--%3E%20CD%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E4%BA%A7%E7%BA%BF%20CD%20%E5%85%AC%E5%BC%8F%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"几何上，两束 TM 光的电矢量随 \\(\\theta\\) 张开，相干叠加的对比度按 \\(\\cos 2\\theta\\) 一类的因子下降（具体形式随归一）。频率上，截止附近的级对夹角最大，所以密图形先付偏振税。这与上一课「高频先死于离焦」同构，只是本课的税在 \\(z=0\\) 就征收。",-1)),a[5]||(a[5]=e("p",null,[t("掩模侧的偏振：透射铬栅会当线栅偏振器，反射 EUV 吸收体也有自己的 s/p 差。那是"),e("a",{href:"/litho/mask-3d-effect"},"掩模 3D"),t("的缺口。本课的物是「投影侧已经进光瞳的矢量场」，不在掩模膜里做电磁边值。")],-1)),a[6]||(a[6]=e("p",null,"非偏振照明是 TE 与 TM 的强度平均，密线得到的 NILS 介于两者之间。要极值对比必须控偏振，不能只加大 \\(\\sigma\\)。分辨率仍由最高频率 \\(\\mathrm{NA}/\\lambda\\) 限制，矢量没有改截止；它改的是同样进了光瞳的两束，调制可能更弱，有效工艺因子更差——后面的瑞利课把这笔打进 \\(k_1\\)。",-1)),a[7]||(a[7]=e("p",null,[e("span",{class:"marginnote"},"数字实例：NA 1.35 时边缘光线的 \\(\\theta\\) 约 69°，两束 TM 电矢量的夹角接近 2θ ≈ 138°，交叉项几乎归零；而 NA 0.3 的老机器 2θ 只有约 35°，交叉项还很丰满——这就是「高 NA 才必须矢量」的分界线。")],-1)),(i(),l(n,null,{default:E(()=>[s(r,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%AF%84%E4%BC%B0%E4%B8%80%E5%BC%A0%E6%8E%A9%E6%A8%A1%EF%BC%9A%E6%A0%87%E9%87%8F%E6%A8%A1%E5%9E%8B%E5%A4%9F%E5%90%97%22%5D%20--%3E%20LOW%5B%22%E4%BD%8E%20NA%E3%80%81%E6%9D%BE%E8%8A%82%E8%B7%9D%22%5D%0A%20%20Q%20--%3E%20HIGH%5B%22%E9%AB%98%20NA%E3%80%81%E5%AF%86%E8%8A%82%E8%B7%9D%22%5D%0A%20%20LOW%20--%3E%20OK%5B%22%E6%A0%87%E9%87%8F%20%7CU%7C%5E2%20%E8%BF%91%E4%BC%BC%E5%8F%AF%E7%94%A8%22%5D%0A%20%20HIGH%20--%3E%20ANG%5B%22%E7%BA%A7%E5%AF%B9%E5%A4%B9%E8%A7%92%E5%A4%A7%EF%BC%8C%E5%AF%B9%E6%AF%94%E6%8C%89%20cos2%CE%B8%20%E5%9B%A0%E5%AD%90%E4%B8%8B%E9%99%8D%22%5D%0A%20%20ANG%20--%3E%20NILS%5B%22NILS%20%E4%BD%8E%E4%BA%8E%E6%A0%87%E9%87%8F%E9%A2%84%E6%9C%9F%22%5D%0A%20%20NILS%20--%3E%20FIX%5B%22%E5%AF%86%E7%BA%BF%E8%B5%B0%20TE%20%E5%81%8F%E6%8C%AF%20%2B%20%E7%9F%A2%E9%87%8F%E6%A8%A1%E5%9E%8B%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=o('<h3 id="后课默认的接口" tabindex="-1">后课默认的接口 <a class="header-anchor" href="#后课默认的接口" aria-label="Permalink to &quot;后课默认的接口&quot;">​</a></h3><p>说到空中像，高 NA 默认 \\(I\\) 是能量沉积，对比度与 NILS 的公式形式不变、输入变了。说到照明，必须声明偏振；只报 \\(\\sigma\\) 不够。不要在瑞利课里回头解释「为什么标量 \\(k_1\\) 会乐观」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不是完整 FDTD。掩模波导、胶内二次电子、EUV 多层膜的偏振反射率，都不在这里展开。也不要把「用了偏振照明」写成已经解决矢量问题：它只是避开最差的 TM 组合。标量模型在低 NA、松节距上仍可用；切换判据是 \\(\\mathrm{NA}\\) 与目标 \\(k_1\\)，不是机台品牌。</p><p>Immersion 水的 \\(n\\) 会改夹角，因而改 TM 损失，但流体缺陷与喷淋头不在本课。后课写瑞利式时，标量 \\(k_1\\) 已经默认「在所用偏振下的能量沉积」，不必再把 0.61 和 Jones 矢量缠在一起。</p><p><span class="marginnote">产线口语里的「极化照明」几乎总是光源侧的线偏振或切向偏振，不是把投影物镜改成偏振器。物镜镀膜的 s/p 透过率差是二阶修正。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>高 NA 下标量 \\(|U|^2\\) 不够；空中像升级为胶内能量沉积。</li><li>TE 干涉深、TM 对比掉，密图形先付偏振税。</li><li>矢量效应在最佳焦距已存在，与离焦二次相位叠加。</li><li>\\(\\sigma\\) 的定义不改；每个源点要带偏振状态。</li><li>TE / TM 对比是下一课；产线 CD 公式在后面的瑞利课，本课不写 \\(k_1\\)。</li><li>出处：Born &amp; Wolf, <em>Principles of Optics</em>；Mack, <em>Fundamental Principles of Optical Lithography</em>；Levinson, <em>Principles of Lithography</em>。</li></ul>',8))])}const F=A(B,[["render",h]]);export{D as __pageData,F as default};
